#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int L;
    scanf("%d", &L);

    char* s = (char*)malloc((L + 1) * sizeof(char));
    scanf("%s", s);

    // Collect positions of empty squares and pieces with direction
    int* empty = (int*)malloc(L * sizeof(int));
    int* piecePos = (int*)malloc(L * sizeof(int));
    char* pieceDir = (char*)malloc(L * sizeof(char));
    int emptyCount = 0, pieceCount = 0;

    for (int i = 0; i < L; i++) {
        if (s[i] == '.') {
            empty[emptyCount++] = i;
        } else {
            piecePos[pieceCount] = i;
            pieceDir[pieceCount] = s[i];
            pieceCount++;
        }
    }

    // Two-pointer greedy match
    int p = 0, e = 0;
    int score = 0;

    while (p < pieceCount && e < emptyCount) {
        int pos = piecePos[p];
        int emp = empty[e];
        char dir = pieceDir[p];

        if (emp < pos) {
            // moving left
            if (dir == '<') {
                score += 1; // moving in arrow direction
            } else {
                score -= 1;
            }
        } else {
            // moving right
            if (dir == '>') {
                score += 1;
            } else {
                score -= 1;
            }
        }
        p++;
        e++;
    }

    printf("%d\n", score);

    free(s);
    free(empty);
    free(piecePos);
    free(pieceDir);

    return 0;
}

