int main() {
    int L, n;
    scanf("%d %d", &L, &n);

    int *pos = malloc(n * sizeof(int));
    char *dir = malloc(n * sizeof(char));

    int n_R = 0, n_L = 0;
    long long constant = 0;

    for (int i = 0; i < n; i++) {
        char d[10];
        scanf("%d %s", &pos[i], d);
        dir[i] = d[0];
        if (dir[i] == 'R') { n_R++; constant -= pos[i]; }
        else { n_L++; constant += pos[i]; }
    }

    // Assign largest n_R positions to R pieces, smallest n_L to L pieces
    long long best = 0;
    // R pieces get positions L, L-1, ..., L-n_R+1
    for (int i = 0; i < n_R; i++) best += (L - i);
    // L pieces get positions 1, 2, ..., n_L (negated)
    for (int i = 0; i < n_L; i++) best -= (i + 1);

    best += constant;

    printf("%lld\n", best);

    free(pos); free(dir);
    return 0;
}

