typedef long long ll;

int main(void) {
    int L, n;
    if (scanf("%d %d", &L, &n) != 2) return 0;

    int *x = (int *)malloc((n + 1) * sizeof(int));
    char *dir = (char *)malloc((n + 1) * sizeof(char));

    for (int i = 1; i <= n; i++) {
        char s[8];
        scanf("%d %s", &x[i], s);
        dir[i] = s[0];
    }

    /*
      Key idea:
      Pieces cannot pass each other, so their left-to-right order is invariant.
      Therefore in any final arrangement, if final positions are y1 < y2 < ... < yn,
      then piece i ends at yi and:
          1 <= y1 < y2 < ... < yn <= L

      Score contribution of piece i moved from x[i] to y[i]:
          +(y[i]-x[i]) if dir[i]=='R'
          +(x[i]-y[i]) if dir[i]=='L'

      So total score is:
          sum( +y[i] ) for R pieces, sum( -y[i] ) for L pieces, plus a constant.
      Hence we maximize a linear function under increasing-position constraints.

      Let z[i] = y[i] - i. Then:
          0 <= z[1] <= z[2] <= ... <= z[n] <= L-n
      and objective becomes sum c[i] * z[i] plus constants,
      where c[i] = +1 for R, -1 for L.

      For monotone z with bounds [0, L-n], optimum is attained by a threshold:
      choose some k, set z[1..k]=0 and z[k+1..n]=L-n.
      Thus:
          y[i] = i            for i <= k
          y[i] = i + (L - n)  for i > k
      i.e. first k pieces packed to the far left, remaining packed to the far right.

      We try all k and compute the score.
    */

    ll base = 0; // constant part from original positions
    ll *pref = (ll *)malloc((n + 1) * sizeof(ll));
    pref[0] = 0;

    for (int i = 1; i <= n; i++) {
        int c = (dir[i] == 'R') ? 1 : -1;
        base += -(ll)c * x[i];
        pref[i] = pref[i - 1] + c;
    }

    int gap = L - n;
    ll ans = -(1LL << 60);

    for (int k = 0; k <= n; k++) {
        // y[i]=i for i<=k, y[i]=i+gap for i>k
        // sum c[i]*i for all i  + gap * sum_{i>k} c[i]
        ll score = base;
        for (int i = 1; i <= n; i++) score += (ll)((dir[i] == 'R') ? 1 : -1) * i;
        score += (ll)gap * (pref[n] - pref[k]);
        if (score > ans) ans = score;
    }

    printf("%lld\n", ans);

    free(x);
    free(dir);
    free(pref);
    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int L = sc.nextInt();
        sc.nextLine();
        String s = sc.nextLine();

        // dp[i][0] = max score up to i, with i empty
        // dp[i][1] = max score up to i, with i occupied by right-pointing piece
        // dp[i][2] = max score up to i, with i occupied by left-pointing piece

        int[][] dp = new int[L + 1][3];
        for (int i = 0; i <= L; i++) {
            dp[i][0] = dp[i][1] = dp[i][2] = Integer.MIN_VALUE;
        }
        dp[0][0] = 0;

        for (int i = 1; i <= L; i++) {
            char c = s.charAt(i - 1);
            if (c == '.') {
                // empty square: can come from empty or after moving a piece away
                dp[i][0] = Math.max(dp[i-1][0], Math.max(dp[i-1][1], dp[i-1][2]));
            } else if (c == 'R') {
                // piece pointing right
                // option 1: leave it here
                dp[i][1] = Math.max(dp[i-1][0], Math.max(dp[i-1][1], dp[i-1][2]));
                // option 2: move it right (if i+1 is empty and exists)
                // handled when we process i+1
            } else { // 'L'
                dp[i][2] = Math.max(dp[i-1][0], Math.max(dp[i-1][1], dp[i-1][2]));
            }

            // Try moving a piece from i-1 into i
            if (c == '.') {
                // can receive a piece from left
                if (dp[i-1][1] != Integer.MIN_VALUE) {
                    // R moving right into empty -> +1
                    dp[i][0] = Math.max(dp[i][0], dp[i-1][1] + 1);
                }
                if (dp[i-1][2] != Integer.MIN_VALUE) {
                    // L moving right (opposite direction) -> -1
                    dp[i][0] = Math.max(dp[i][0], dp[i-1][2] - 1);
                }
            }

            // If current is occupied, could have moved from left into it
            if (c == 'R') {
                if (dp[i-1][0] != Integer.MIN_VALUE) {
                    // empty to R: incoming piece from left? Actually R is already here,
                    // this means we consider moving a piece from i-1 to i? No, R is already piece.
                }
            }
        }

        int result = Math.max(dp[L][0], Math.max(dp[L][1], dp[L][2]));
        System.out.println(result);
    }
}

