public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int L = sc.nextInt();
        int N = sc.nextInt(); // number of pieces

        int[] pos = new int[N];
        char[] dir = new char[N];

        // Read pieces - need to sort by position
        int[][] pieces = new int[N][2]; // position, direction (0=L, 1=R)
        for (int i = 0; i < N; i++) {
            pos[i] = sc.nextInt();
            String d = sc.next();
            dir[i] = d.charAt(0);
        }

        // Sort pieces by position
        Integer[] idx = new Integer[N];
        for (int i = 0; i < N; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> pos[a] - pos[b]);

        int[] sortedPos = new int[N];
        char[] sortedDir = new char[N];
        for (int i = 0; i < N; i++) {
            sortedPos[i] = pos[idx[i]];
            sortedDir[i] = dir[idx[i]];
        }

        // dp[j] = max score with current piece placed at square j (1-indexed)
        final int NEG_INF = Integer.MIN_VALUE / 2;
        int[] dp = new int[L + 1];
        Arrays.fill(dp, NEG_INF);

        for (int j = 1; j <= L; j++) {
            dp[j] = score(sortedDir[0], sortedPos[0], j);
        }

        for (int i = 1; i < N; i++) {
            int[] ndp = new int[L + 1];
            Arrays.fill(ndp, NEG_INF);
            int prefMax = NEG_INF;
            for (int j = 1; j <= L; j++) {
                if (dp[j] != NEG_INF) prefMax = Math.max(prefMax, dp[j]);
                if (prefMax != NEG_INF) {
                    ndp[j + 1 <= L ? j + 1 : j] = NEG_INF; // placeholder
                    if (j + 1 <= L) ndp[j + 1] = Math.max(ndp[j + 1], prefMax + score(sortedDir[i], sortedPos[i], j + 1));
                }
            }
            // Actually need j' < j
            prefMax = NEG_INF;
            for (int j = 2; j <= L; j++) {
                if (dp[j-1] != NEG_INF) prefMax = Math.max(prefMax, dp[j-1]);
                if (prefMax != NEG_INF) ndp[j] = Math.max(ndp[j], prefMax + score(sortedDir[i], sortedPos[i], j));
            }
            dp = ndp;
        }

        int ans = Arrays.stream(dp).max().getAsInt();
        System.out.println(ans);
    }

    static int score(char dir, int from, int to) {
        return dir == 'R' ? (to - from) : (from - to);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line1 = br.readLine();
        if (line1 == null || line1.trim().isEmpty()) return;
        int L = Integer.parseInt(line1.trim());

        String s = br.readLine();
        if (s == null) s = "";
        s = s.trim();

        // DP over positions.
        // Let balance = (# of '>' pieces already seen) - (# of '<' pieces not yet seen)
        // If we place a hole at current position, score changes by current balance.
        // Occupied positions contribute no immediate score.
        //
        // Initially, before scanning:
        // seenRight = 0
        // unseenLeft = totalLeft
        // so balance = -totalLeft
        //
        // When processing a piece:
        // '>' increases balance by +1 after this position
        // '<' increases balance by +1 as well, because unseenLeft decreases by 1
        //
        // Therefore every piece increments balance by 1 after its position, regardless of type.
        //
        // DP state:
        // dp[k] = max score after processing some prefix, where current balance = startBalance + k
        // Since each piece increments balance by 1, k is simply the number of pieces processed so far.
        // But occupied/empty pattern is fixed, so we can do simpler:
        //
        // Let p = number of pieces processed so far.
        // balance = -totalLeft + p.
        // For each position:
        // - if empty: add balance
        // - if piece: p++
        //
        // Sum over all empty positions gives the maximum score.

        int totalLeft = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '<') totalLeft++;
        }

        long ans = 0;
        int piecesSeen = 0;

        for (int i = 0; i < L; i++) {
            char c = (i < s.length() ? s.charAt(i) : '.');
            if (c == '<' || c == '>') {
                piecesSeen++;
            } else {
                ans += -totalLeft + piecesSeen;
            }
        }

        System.out.println(ans);
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L;
    string s;
    cin >> L >> s;

    // dp[i][j] = max score considering first i positions, with j unmatched pieces
    // j can be negative: means we have empty slots waiting for pieces
    const int INF = -1e9;
    int offset = L; // to shift index for dp
    vector<int> dp(2 * L + 5, INF);
    dp[offset] = 0;

    for (int i = 0; i < L; i++) {
        vector<int> ndp(2 * L + 5, INF);
        for (int bal = -L; bal <= L; bal++) {
            int idx = bal + offset;
            if (dp[idx] == INF) continue;
            if (s[i] == '.') {
                // empty square: can be filled by a piece from the right later
                // either leave empty (bal+1) or fill from left (no change? Actually need piece to fill)
                // Option: treat as waiting empty slot
                ndp[bal + 1 + offset] = max(ndp[bal + 1 + offset], dp[idx]);
                // Or fill now if we have a waiting piece
                if (bal > 0) {
                    // we fill this empty with a piece that was waiting
                    // the piece came from somewhere, cost depends on its arrow
                    // But we don't know arrow here — we need to incorporate direction when piece is "used"
                    // So we don't fill here; we handle piece placement when we see piece.
                }
            } else {
                int dir = (s[i] == 'R') ? 1 : -1;
                // piece: can move left or right to fill empty
                // Option: move left (cost = -dir)
                // bal > 0 means there is empty to left? Actually bal indicates net pieces waiting to be placed.
                // If bal > 0: there are unplaced pieces; if bal < 0: empty slots waiting.

                // Move left: consumes an empty slot to the left (bal becomes bal-1)
                // Score change: moving left => if arrow is left (+1) else (-1)
                int score_left = (dir == -1) ? 1 : -1;
                if (bal > -L) // there is an empty slot to the left
                    ndp[bal - 1 + offset] = max(ndp[bal - 1 + offset], dp[idx] + score_left);

                // Move right: creates an empty slot to the left (bal becomes bal+1)
                int score_right = (dir == 1) ? 1 : -1;
                ndp[bal + 1 + offset] = max(ndp[bal + 1 + offset], dp[idx] + score_right);
            }
        }
        dp.swap(ndp);
    }

    // At the end, balance must be 0
    cout << dp[offset] << "\n";

    return 0;
}

