#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L;
    if (!(cin >> L)) return 0;
    string s;
    cin >> s;

    // s length is L.
    // '.' = empty, 'L' = piece with left arrow, 'R' = piece with right arrow.
    //
    // Key observation:
    // Pieces cannot pass through each other, so their relative order is fixed.
    // Any reachable final configuration is obtained by assigning each piece to a distinct square,
    // in the same order as initially.
    //
    // If a piece initially at position p ends at q:
    //   score contribution = +(q-p) for 'R'
    //                        +(p-q) for 'L'
    // i.e. maximize sum of signed displacements.
    //
    // Since order is fixed, to maximize total score:
    // - 'L' pieces want to be as far left as possible,
    // - 'R' pieces want to be as far right as possible.
    //
    // This is exactly achieved by:
    //   all 'L' pieces packed to the left, preserving order,
    //   all 'R' pieces packed to the right, preserving order.
    //
    // Then we can compute the total directly.

    vector<int> posL, posR;
    for (int i = 0; i < L; ++i) {
        if (s[i] == 'L') posL.push_back(i + 1); // 1-indexed
        else if (s[i] == 'R') posR.push_back(i + 1);
    }

    long long ans = 0;

    // Final positions for L pieces: 1, 2, ..., cntL
    for (int i = 0; i < (int)posL.size(); ++i) {
        int finalPos = i + 1;
        ans += (long long)posL[i] - finalPos;
    }

    // Final positions for R pieces: L-cntR+1, ..., L
    int cntR = (int)posR.size();
    for (int i = 0; i < cntR; ++i) {
        int finalPos = L - cntR + 1 + i;
        ans += (long long)finalPos - posR[i];
    }

    cout << ans << '\n';
    return 0;
}
